style.css:
@-moz-document domain("www.thingiverse.com") {
/* ====================================================================
     Thingiverse drives nearly every surface, border, text and accent
     through a single set of `--tv-*` design tokens on :root. Retoning
     those re-themes the bulk of the React app at once (same approach as
     Khan's Wonder Blocks). Light neutrals -> dark palette; the brand blue
     and semantic status colors are refined, not dropped, below.
     ==================================================================== */
  :root {
    color-scheme: dark !important;

    /* ---- Surfaces (page, layers, hover, selected) ---- */
    --tv-bg-main: #14181d !important;
    --tv-bg-layer-01: #1c2128 !important;
    --tv-bg-layer-02: #14181d !important;
    --tv-bg-layer-03: #1c2128 !important;
    --tv-bg-hover: #2d333b !important;
    --tv-bg-layer-hover-01: #21262d !important;
    --tv-bg-layer-hover-02: #21262d !important;
    --tv-bg-layer-hover-03: #21262d !important;
    --tv-bg-selected: #1d2a3a !important;
    --tv-bg-layer-selected-01: #1d2a3a !important;
    --tv-bg-layer-selected-02: #1d2a3a !important;
    --tv-bg-layer-selected-03: #1d2a3a !important;
    --tv-bg-disabled: #2d333b !important;
    --tv-bg-inverse-primary: #e6edf3 !important;
    --tv-bg-inverse-secondary: #c4cdd6 !important;

    /* ---- Neutral ramp: was light->dark greys, now dark->light ---- */
    --tv-neutral-faint: #1c2128 !important;
    --tv-neutral-subtle: #262c33 !important;
    --tv-neutral-muted: #8b949e !important;
    --tv-neutral-main: #9aa4af !important;
    --tv-neutral-strong: #c4cdd6 !important;
    --tv-neutral-bold: #e6edf3 !important;
    --tv-neutral-ink: #e6edf3 !important;

    /* ---- Foreground text ---- */
    --tv-content-primary: #e6edf3 !important;
    --tv-content-secondary: #9aa4af !important;
    --tv-content-disabled: #8b949e !important;
    /* "inverse" = text that sits on dark/colored surfaces (white CTA labels,
       captions over the dark scrim on model hero cards) — keep it light */
    --tv-content-inverse: #ffffff !important;

    /* ---- Borders / dividers (soften bright default lines) ---- */
    --tv-border-faint: #1c2128 !important;
    --tv-border-subtle: #262c33 !important;
    --tv-border-inverse: #2d333b !important;
    /* on-primary/on-secondary draw control outlines (checkbox box, checked
       checkbox, active pagination underline) that used to sit on white. Keep
       them light enough to read on the dark surfaces they now sit on. */
    --tv-border-on-primary: #e6edf3 !important;
    --tv-border-on-secondary: #8b949e !important;

    /* ---- white/black aliases that some components paint directly ---- */
    --tv-white: #1c2128 !important;
    --tv-black: #e6edf3 !important;

    /* ---- Brand blue (MakerBot blue #2b52fe): keep the identity but
       lift it so links/accents read on near-black instead of glowing ---- */
    --tv-brand-main: #5fb0e6 !important;
    --tv-brand-strong: #9bd4ff !important;
    --tv-brand-bold: #9bd4ff !important;
    --tv-brand-muted: #4f86c6 !important;
    --tv-brand-subtle: #18222f !important;
    --tv-brand-faint: #18222f !important;
    --tv-brand-ink: #9bd4ff !important;
    --tv-content-accent: #5fb0e6 !important;
    --tv-content-accent-light: #9bd4ff !important;
    --tv-content-accent-dark: #9bd4ff !important;
    --tv-border-accent: #5fb0e6 !important;
    --tv-border-accent-light: #4f86c6 !important;
    --tv-bg-accent-light: #18222f !important;
    --tv-bg-accent-light-hover: #1d2a3a !important;

    /* Primary CTA fill keeps the Khan-style refined blue so white button
       text stays crisp on the dark UI */
    --tv-bg-accent: #2563c9 !important;
    --tv-bg-accent-hover: #2f6fd6 !important;
    --tv-bg-accent-active: #1d51b0 !important;
    --tv-bg-accent-medium: #2563c9 !important;

    /* ---- Semantic colors: preserve meaning, just deepen surfaces ---- */
    --tv-bg-positive-light: #122a25 !important;
    --tv-bg-positive-light-hover: #18352e !important;
    --tv-positive-subtle: #122a25 !important;
    --tv-positive-faint: #122a25 !important;
    --tv-bg-negative-light: #2a1419 !important;
    --tv-bg-negative-light-hover: #371a20 !important;
    --tv-negative-subtle: #2a1419 !important;
    --tv-negative-faint: #2a1419 !important;
    --tv-bg-warning-light: #2a2410 !important;
    --tv-bg-warning-light-hover: #352e14 !important;
    --tv-warning-subtle: #2a2410 !important;
    --tv-warning-faint: #2a2410 !important;
    --tv-highlight-subtle: #221833 !important;
    --tv-highlight-faint: #221833 !important;
    --tv-bg-highlight-light: #221833 !important;

    /* The `*-dark` aliases resolve to the `*-ink` ramp — very dark status text
       (#6b1827 red, #004c43 teal, #6b5201 amber, #290064 purple) that the site
       paints on its LIGHT status tints. Those tints are dark now, so the ink
       would be dark-on-dark. Flip each to the light end of its own hue so the
       status meaning survives (.text-color--negative-dark & friends). */
    --tv-content-negative-dark: #ff8fa3 !important;
    --tv-content-positive-dark: #6fd8c9 !important;
    --tv-content-warning-dark: #ffd75c !important;
    --tv-content-highlight-dark: #c4a2ff !important;
    /* Same trap one alias over: `--tv-content-*` resolve to the `*-main` ramp,
       and three of those four (#ff385c red, #01b49f teal, #ffc402 amber) already
       read on dark — but `--tv-content-highlight` is --tv-highlight-main #6200ee,
       a deep purple drawn for the white page. It inks `.text-color--highlight`
       and the IconBadge highlight glyph, both of which sit on dark now (1.6:1).
       Lift the TEXT alias only: #6200ee stays the SURFACE hue on the AI card
       badge and the AI corner flag. */
    --tv-content-highlight: #c4a2ff !important;

    /* Toastify (in-app toasts) */
    --toastify-color-light: #1c2128 !important;
    --toastify-toast-background: #1c2128 !important;
    --toastify-text-color-light: #c4cdd6 !important;
  }

  /* ====================================================================
     Base surfaces
     ==================================================================== */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  #react-app, .react-app { background-color: #14181d !important; }

  /* Cookiebot injects bare sync <iframe>s with no width/height set, so they
     render at the browser default 304×154 with a 2px `inset` border drawn in
     `currentColor`. Our light body `color` makes that default border glow as
     two white boxes at the top of every page (native they inherit the site's
     dark-navy text, so they hide against white). Mute the border to the page
     background — the site's own consent DIALOG is left untouched. The `inset` style
     must be flattened to `solid` as well: its bevel derives its own light shades and
     stays visible as three outlined boxes however dark we colour it. (Cookiebot's SDK
     display:nones these iframes once it boots; until then they lay out at the default
     size on every page load.) */
  iframe.CybotCookiebotHiddenIframe,
  iframe.CybotCookiebotOffscreenIframe {
    border-color: #14181d !important; border-style: solid !important; }

  /* Cookiebot's consent DIALOG keeps its own WHITE panel (a third-party CMP we
     deliberately don't retheme) — but our page-wide ink rules reach inside it and
     paint light-on-white. The whole family: `p/li/dd/dt/td/th/label/time/small`
     and `h1-h6` repaint its copy in the page greys (every Details-tab cookie card
     is an <li>, so its heading AND description wash out); `[role="tab"]` greys the
     Consent/Details/Ad Settings/About nav and `[role="tab"][aria-selected="true"]`
     paints the CURRENT tab #ffffff, erasing it; `[class*="footer"]` drops a
     #0d1117 block into each cookie-declaration card. Restore the CMP's own
     near-black ink and its MakerBot-blue link/active-tab accent. (Its checkboxes
     are 0x0 behind styled sliders, so the `input` rule below never shows.) */
  #CybotCookiebotDialog, #CybotCookiebotDialog h1, #CybotCookiebotDialog h2,
  #CybotCookiebotDialog h3, #CybotCookiebotDialog h4, #CybotCookiebotDialog h5,
  #CybotCookiebotDialog h6, #CybotCookiebotDialog p, #CybotCookiebotDialog li,
  #CybotCookiebotDialog dd, #CybotCookiebotDialog dt, #CybotCookiebotDialog td,
  #CybotCookiebotDialog th, #CybotCookiebotDialog caption,
  #CybotCookiebotDialog figcaption, #CybotCookiebotDialog blockquote,
  #CybotCookiebotDialog label, #CybotCookiebotDialog time,
  #CybotCookiebotDialog small, #CybotCookiebotDialog [role="tab"],
  #CybotCookiebotDialog [role="tab"]:hover { color: #141414 !important; }
  #CybotCookiebotDialog a,
  #CybotCookiebotDialog [role="tab"][aria-selected="true"] {
    color: #2b52fe !important; border-bottom-color: #2b52fe !important; }
  #CybotCookiebotDialog [class*="Footer"], #CybotCookiebotDialog [class*="footer"] {
    background-color: transparent !important; border-color: #d6d6d6 !important;
    color: #141414 !important; }

  /* ====================================================================
     Content-area neutralizer — Thingiverse's React shell renders most
     panels, cards and bars through HASHED styled-component classnames
     (App__app--xxxxx, ItemCardContentWrapper__..., DetailContents__...).
     Those hashes change on every deploy, so instead of chasing them we
     flatten any stray light surface under the stable #react-app wrapper
     onto the dark page. No `!important`, so it overrides the hashed
     backgrounds (which aren't important) while still yielding to the
     token-driven dark surfaces and the explicit `!important` rules below.
     ==================================================================== */
  #react-app [class] { background-color: transparent; }

  /* ====================================================================
     Floating / sticky / fixed bars MUST stay opaque — the neutralizer
     above would leave them see-through, so scrolling content (model
     thumbnails) bleeds through. Re-establish a solid dark background on
     the fixed top header and the sticky search/sort/filter toolbar so
     they cleanly cover whatever scrolls underneath. (Dropdowns, menus,
     popovers, tooltips and the autocomplete panel get their own opaque
     dark surfaces in the dropdown section below; the cookie dialog is the
     site's own and is left untouched.) Stable class-prefix anchors. */
  [class*="PageHeader__pageHeader"], [class*="StickyHeader"],
  [class*="pageHeader"][class*="sticky"] {
    background-color: #0d1117 !important; }
  [class*="SearchFilterBar__searchFilterBarWrapper"],
  [class*="searchFilterBarWrapper"], [class*="SearchFilterBar__searchFilterBar"],
  [class*="SearchSort__searchSortWrapper"] {
    background-color: #14181d !important; }

  /* Home promo banner carousel: each 1268px slide centers a narrower (~970px) promo
     image and carries an INLINE `background-color` that marketing matches to that
     image's own artwork (#3c78d6 blue, #f1c232 gold, #cc4125 red, #999 grey), so the
     band either side of the image continues the promo edge-to-edge. Only the CONTAINER
     may go dark — it shows above and below the slide. The `--` is load-bearing: a bare
     `[class*="HomePageBanner__homeBanner"]` also matches `homeBannerSlide` (substring),
     which is what cut two dark letterbox bars into every banner. */
  [class*="HomePageBanner__homeBanner--"] { background-color: #14181d !important; }
  /* The banner's pager dots are plain white at opacity .3/1 over a dark box-shadow,
     drawn to read on that coloured artwork — the dark fill the generic carousel rule
     below gives them turned the whole pager into dark blobs on the promo. */
  [class*="HomePageBanner__homeBanner--"] .carousel .control-dots .dot,
  [class*="HomePageBanner__homeBanner--"] .carousel .control-dots .dot.selected {
    background-color: #ffffff !important; }

  /* The membership hero is a brand gradient that runs MakerBot blue down to
     #f6f7fa — drawn to hand off into the white page below it. On dark it ends in
     a near-white band butted against the page base. Keep the blue top and land
     the gradient on the page colour instead. */
  [class*="AboutMembershipPage__aboutMembershipHero"] {
    background-image: linear-gradient(#1e42df 14%, #3a5fe0 41%, #24304f 84%, #1a1f28 93%, #14181d 100%) !important; }

  /* ====================================================================
     Card / panel surfaces — Thingiverse wraps the model-page gallery,
     description and most content blocks in `Card__card` / `Card__layer--NN`
     panels that paint white via `var(--tv-bg-layer-01)`. The neutralizer
     above would flatten them onto the page, but their inner image carousel
     is transparent, so the panel's own background is what shows around and
     above letterboxed photos (the white band + white thumbnail tiles).
     Re-establish these stable-prefix panels as the dark elevated surface so
     the gallery stage and tiles sit on dark, never white — the <img> photos
     keep their true color (we never recolor images). */
  [class*="Card__card"], [class*="Card__layer"] {
    background-color: #1c2128 !important; }

  /* ====================================================================
     Login / Join (AuthPage) — the auth form sits in an `AuthCard__authCard`
     panel that paints white via the layer token. The neutralizer flattens it
     to transparent, so the email/password form and buttons bleed over the
     decorative 3D-model montage ring behind it (unreadable). Re-establish the
     card as a solid dark elevated surface so the form reads cleanly. The
     "Continue with Google" button is Google's official `gsi-material-button`
     (white surface, near-black brand text per Google's brand guidelines) — the
     neutralizer stripped its white fill, leaving dark-on-dark; restore the
     white surface so its mandated dark label is legible again. */
  [class*="AuthCard__authCard"] {
    background-color: #1c2128 !important; }
  .gsi-material-button { background-color: #ffffff !important; }
  /* AuthPage titles ("Welcome back!", "Continue with email") are drawn by
     EntryView header/title classes in the site's dark-navy heading colour
     (#12226b) — not h1-h6 and not token-driven, so they render dark-on-dark on
     the now-dark card. Lift to the primary light ink. */
  [class*="EntryView__header"], [class*="EntryView__introTitle"] {
    color: #e6edf3 !important; }

  /* ====================================================================
     Semantic fills the neutralizer eats. `#react-app [class]` outranks every
     single-class background rule the site writes, so each of these carries its
     entire meaning in a `background-color` that got flattened to transparent:
     a card's "New"/"Featured"/"Verified"/"Work in Progress" dot, the avatar's
     Featured/Verified Creator flair, the header's unread counter, the "this
     filter section is active" dot, the selected option in a picker. Restore
     each with the site's own hue (retoned only where it must read on dark).
     Class hashes change per deploy, so anchor on the stable prefix.
     ==================================================================== */
  [class*="cardBadge--new"], [class*="cardBadge--source"] { background-color: #2563c9 !important; }
  [class*="cardBadge--featured"] { background-color: #718bfe !important; }
  [class*="cardBadge--verified"] { background-color: #01b49f !important; }
  [class*="cardBadge--contest"] { background-color: #ffc402 !important; }
  [class*="cardBadge--ai"] { background-color: #6200ee !important; }
  /* wip keeps a slate fill ringed in the site's warning yellow */
  [class*="cardBadge--wip"] { background-color: #525b75 !important; border-color: #ffd755 !important; }

  [class*="featuredFlair"] { background-color: #2563c9 !important; }
  [class*="verifiedFlair"] { background-color: #01b49f !important; }

  /* Corner-ribbon Flags (title="Featured"/"Challenge Winner"/"Verified"/"AI"...)
     floated on a thing's hero/card image. The whole meaning is a coloured flag
     background (primary=brand blue, winner=gold, verified=teal, ai=purple, ...)
     with a small icon disc inside; the neutralizer ate every flag's fill,
     leaving just the disc ring so the marker read as an empty outlined button
     (and the AI variant's dark-purple icon went near dark-on-dark). Restore each
     flag's hue, and put the icon disc back on a light surface so the site's
     coloured icon (drawn in the flag's own hue) pops on it, as it does natively. */
  [class*="Flag__primary"] { background-color: #2563c9 !important; }
  [class*="Flag__winner"] { background-color: #ffc402 !important; }
  [class*="Flag__verified"] { background-color: #01b49f !important; }
  [class*="Flag__ai"] { background-color: #6200ee !important; }
  [class*="Flag__warn"] { background-color: #ff9800 !important; }
  [class*="Flag__default"] { background-color: #525b75 !important; }
  [class*="Flag__flagIconWrapper"] { background-color: #ffffff !important; }
  /* `GradientFlag` is a SECOND flag family whose class names contain `Flag__…`, so the
     rules above also match it — but it inverts the icon disc: its wrapper is a translucent
     BLACK scrim (rgba(0,0,0,.2)) under a WHITE glyph, not a white disc under a coloured
     one. The `#ffffff` above therefore painted a white glyph on a white disc. Restore the
     native scrim (the variant fills above are correct for it and stay). */
  [class*="GradientFlag__flagIconWrapper"] { background-color: rgba(0, 0, 0, 0.2) !important; }

  /* Collection cards (profile > Collections, /<user>/collections) carry their
     whole identity in colour: the site paints the card panel MakerBot-indigo
     (#5575fe) and stacks four concentric circles on it (#718bfe -> #eaeeff,
     largest to smallest) to build a radial indigo wash, with the collection
     title in white on top. Every one of those is a plain `background-color` on
     a single class, so the neutralizer ate all five — collection cards rendered
     as bare dark boxes, indistinguishable from ordinary thing cards. Restore
     the ramp in the same hue, compressed into the dark range so the white title
     still reads on it. (The featured variant keeps the site's own #5a79ff ring.) */
  [class*="CollectionCard"] [class*="itemCardContentWrapper"],
  [class*="collectionCardContentWrapper"] { background-color: #1e2750 !important; }
  [class*="CollectionCard__circle1"] { background-color: #2a3563 !important; }
  [class*="CollectionCard__circle2"] { background-color: #313e75 !important; }
  [class*="CollectionCard__circle3"] { background-color: #3a4988 !important; }
  [class*="CollectionCard__circle4"] { background-color: #45549e !important; }

  [class*="filterSectionIndicator"], [class*="detailSidebarButtonCounter"],
  [class*="indicatorBar"], [class*="Badge__primary"] { background-color: #2563c9 !important; }
  /* Sort-bar "New" pill (marks the Fresh Makes tab): a filled brand-blue badge
     with white text natively; the neutralizer ate the fill, leaving bare white
     text with no pill, so the "new" emphasis is lost. */
  [class*="SearchSort__newBadge"] { background-color: #2563c9 !important; color: #ffffff !important; }
  [class*="thingCardAIBadge"] { background-color: #6200ee !important; }
  [class*="PageHeader__counter"] { background-color: #ff385c !important; border-color: #ff385c !important; }

  /* Hero carousel pager: the selected slide's dot is the ONLY indicator of
     where you are in the carousel, and it is drawn purely as a fill+border. */
  .carousel .control-dots .dot {
    background-color: #18222f !important; border-color: #4f86c6 !important; }
  .carousel .control-dots .dot.selected,
  .carousel .control-dots .dot:hover {
    background-color: #2563c9 !important; border-color: #9bd4ff !important; }

  /* Sort pills (Popular / Newest / Most Makes / Relevant). They are ghost
     buttons, so the ghost rule would paint every label accent-blue and the
     selected one would be indistinguishable. */
  [class*="searchSortButton"].tv-button {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  [class*="searchSortButton"].tv-button:hover { background-color: #21262d !important; }
  [class*="searchSortButton"].tv-button[class*="isSelected"] {
    background-color: #18222f !important; color: #9bd4ff !important; border-color: #5fb0e6 !important; }

  /* Gallery image-name chip floats on the photo (native: translucent white) */
  [class*="mediaItemName"] { background-color: rgba(0, 14, 26, 0.55) !important; color: #ffffff !important; }

  /* Inline status notifications: tint + coloured edge stripe carry the meaning */
  [class*="Notification__success"] { background-color: #122a25 !important; }
  [class*="Notification__error"] { background-color: #2a1419 !important; }
  [class*="Notification__warning"] { background-color: #2a2410 !important; }
  [class*="Notification__info"] { background-color: #18222f !important; }
  [class*="Notification__success"] [class*="notificationBorderHighlight"] { background-color: #01b49f !important; }
  [class*="Notification__error"] [class*="notificationBorderHighlight"] { background-color: #ff385c !important; }
  [class*="Notification__warning"] [class*="notificationBorderHighlight"] { background-color: #ffc402 !important; }
  [class*="Notification__info"] [class*="notificationBorderHighlight"] { background-color: #5fb0e6 !important; }
  /* The NEUTRAL variant is the same two-part shape as the four above — an elevated
     panel plus an edge stripe, each a single-class `background-color` the
     neutralizer eats — so it rendered as bare text on the page while its coloured
     siblings kept their panels. */
  [class*="Notification__neutral"] { background-color: #1c2128 !important; }
  [class*="Notification__neutral"] [class*="notificationBorderHighlight"] {
    background-color: #2d333b !important; }

  /* IconBadge: a status-tinted disc under a status-coloured glyph, one tint per
     variant, every one a single-class `background-color` the neutralizer eats,
     leaving a bare glyph with no badge behind it. Same tints as the Notification
     panels so the two components keep reading as the same status. `neutral` is the
     sixth member of the set; it needs the same one-step lift off the page as the five
     tints, not `--tv-bg-layer-02`, which equals the page base and shows nothing. */
  [class*="IconBadge__success"] { background-color: #122a25 !important; }
  [class*="IconBadge__error"] { background-color: #2a1419 !important; }
  [class*="IconBadge__warning"] { background-color: #2a2410 !important; }
  [class*="IconBadge__info"] { background-color: #18222f !important; }
  [class*="IconBadge__highlight"] { background-color: #221833 !important; }
  [class*="IconBadge__neutral"] { background-color: #262c33 !important; }

  /* Inline text highlight (matched search terms): the tint IS the highlight, so
     flattening it erases the marking entirely. */
  .tv-text-highlight { background-color: #18222f !important; }

  /* Magic-link "check your inbox" step (/login -> Send link). The green "link
     sent" confirmation tint and the decorative icon disc (native #eaeeff) are
     both single-class fills the neutralizer flattens, so the confirmation lost
     its positive colour and the disc vanished. */
  [class*="CheckInboxView__linkSentBanner"] { background-color: #122a25 !important; }
  /* The disc also INKS the glyph inside it, hardcoded to the raw brand blue #2b52fe that
     was drawn for the native #eaeeff disc — on the dark disc that is 2.6:1. Lift the glyph
     with the surface. */
  [class*="CheckInboxView__iconCircle"] {
    background-color: #1e2750 !important; color: #9bd4ff !important; }
  /* The step's heading is a <span>, not a heading element, so the h1-h6 rule never reaches
     it: it keeps the site's dark-navy #12226b and reads 1.1:1 on the dark auth card. */
  [class*="CheckInboxView__title--"] { color: #e6edf3 !important; }

  /* Thing-page status banners (Banner__banner): the site paints these as a
     SOLID status bar — the WIP banner ("Hey! This Thing is still a Work in
     Progress") is bold amber #ffc402, moderation banners red #ff385c, etc. The
     neutralizer eats the fill, so the whole bar collapses to bare text on the
     page and the status identity is lost. Restore each as the dark status tint
     (matching the Notification treatment) with its own hue for text, so the
     warning/error/info meaning survives on dark. The variant set is exactly
     `default | primary | danger | warning | success` — these names ARE the
     component's API, so a rule keyed to any other word matches nothing. */
  [class*="Banner__warning"] { background-color: #2a2410 !important; color: #ffd75c !important; }
  [class*="Banner__danger"] { background-color: #2a1419 !important; color: #ff8fa3 !important; }
  [class*="Banner__success"] { background-color: #122a25 !important; color: #6fd8c9 !important; }
  [class*="Banner__primary"] { background-color: #18222f !important; color: #9bd4ff !important; }
  [class*="Banner__default"] { background-color: #2d333b !important; color: #c4cdd6 !important; }

  /* Site-wide alert bars keep their native status colours */
  [class*="SiteWideNotification__ok"] { background-color: #018071 !important; }
  [class*="SiteWideNotification__info"] { background-color: #b36b00 !important; }
  [class*="SiteWideNotification__problem"] { background-color: #a3253d !important; }
  [class*="SiteWideNotification__tv"] { background-color: #1d51b0 !important; }

  /* ====================================================================
     Buttons — Thingiverse uses a stable `tv-button` BEM system, not hashed
     classes. The neutralizer above strips every variant's fill (it is an
     #id rule, so it beats the site's own single-class background rules), so
     each variant has to be re-established here. `!important` beats the
     neutralizer regardless of specificity.

     `tv-button--link` is NOT a visual variant: the site defines it as
     `box-sizing:border-box` only. It is added whenever a button renders as
     an <a>. Treating it as a ghost/text variant stripped the fill off every
     anchor CTA on the site ("Go ad-free!", "Sign up", "See Files",
     "Discover more", 404's "Back to Thingiverse"), so it is deliberately
     absent below and inherits whatever colour variant it is paired with.
     ==================================================================== */
  /* primary CTA: brand blue fill + white label (Download, Explore, Log In) */
  .tv-button--primary {
    background-color: #2563c9 !important; color: #ffffff !important; border-color: #2563c9 !important; }
  .tv-button--primary:hover { background-color: #2f6fd6 !important; border-color: #2f6fd6 !important; }
  .tv-button--primary:active { background-color: #1d51b0 !important; border-color: #1d51b0 !important; }
  .tv-button--primary * { color: #ffffff !important; }

  /* secondary: the site's OUTLINED accent button (transparent fill, accent
     label + accent border) — not a neutral grey button */
  .tv-button--secondary {
    background-color: transparent !important; color: #5fb0e6 !important; border-color: #5fb0e6 !important; }
  .tv-button--secondary:hover { background-color: #18222f !important; color: #9bd4ff !important; border-color: #9bd4ff !important; }

  /* outlineNeutral: elevated dark surface, light label */
  .tv-button--outlineNeutral {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .tv-button--outlineNeutral:hover { background-color: #2d333b !important; }
  .tv-button--outlineNeutral * { color: #e6edf3 !important; }

  /* ghost: transparent, brand-blue label lifted for dark. Borderless. */
  .tv-button--ghost { background-color: transparent !important; color: #5fb0e6 !important; }
  .tv-button--ghost:hover { color: #9bd4ff !important; background-color: #18222f !important; }
  /* neutral ghost (like/collect counters, pagination arrows) -> readable light */
  .tv-button--ghostNeutral { background-color: transparent !important; color: #c4cdd6 !important; }
  .tv-button--ghostNeutral:hover { background-color: #21262d !important; }

  /* destructive variants: keep the site's negative red, or a delete button
     reads as an ordinary borderless control */
  .tv-button--danger {
    background-color: #ff385c !important; color: #ffffff !important; border-color: #ff385c !important; }
  .tv-button--danger:hover { background-color: #b52841 !important; border-color: #b52841 !important; }
  .tv-button--danger:active { background-color: #8c1f33 !important; border-color: #8c1f33 !important; }
  .tv-button--danger * { color: #ffffff !important; }
  .tv-button--outlineDanger {
    background-color: transparent !important; color: #ff385c !important; border-color: #ff385c !important; }
  .tv-button--outlineDanger:hover { background-color: #2a1419 !important; }

  /* whiteTransparent: an overlay control that floats on top of a photo. Its
     native translucent-WHITE scrim would swallow our light label, so invert
     it to the site's own dark overlay tone and keep the label white. */
  .tv-button--whiteTransparent {
    background-color: rgba(0, 14, 26, 0.55) !important; color: #ffffff !important; border-color: transparent !important; }
  .tv-button--whiteTransparent:hover { background-color: rgba(0, 14, 26, 0.78) !important; }

  /* disabled must never look enabled: the variant fills above are
     `!important`, so [disabled] has to win on specificity */
  .tv-button[disabled] {
    background-color: #2d333b !important; color: #8b949e !important; border-color: #2d333b !important; }
  .tv-button[disabled] * { color: #8b949e !important; }
  .tv-button--ghost[disabled], .tv-button--ghostNeutral[disabled],
  .tv-button--secondary[disabled], .tv-button--outlineDanger[disabled],
  .tv-button--outlineNeutral[disabled] {
    background-color: transparent !important; }
  /* The site draws `border-color: transparent` on every disabled variant that has no
     fill, so a disabled control loses its outline entirely. Giving them a visible
     muted border instead boxed the DISABLED pagination arrows while the ENABLED ones
     stayed bare — the dead control read as the actionable one. `--secondary` is the
     one exception: the site keeps `--tv-neutral-subtle` on it. */
  .tv-button--ghost[disabled], .tv-button--ghostNeutral[disabled],
  .tv-button--outlineDanger[disabled], .tv-button--outlineNeutral[disabled] {
    border-color: transparent !important; }
  .tv-button--secondary[disabled] { border-color: #262c33 !important; }

  /* Tailwind's `text-white` / `text-white!` utilities compile to
     `color: var(--tv-white)`, and `--tv-white` is the alias retoned above to the
     elevated dark surface (it is what turns the site's `bg-white` panels dark) — so a
     utility asking for WHITE TEXT resolves to that dark surface colour instead. The
     bang form's `!important` sits in a Tailwind utility cascade layer, which outranks
     any unlayered `!important` we can write, so a `color:` override cannot win here;
     redefining the variable does, because custom-property resolution is layer-agnostic.
     The site spends this on the orange "Remove ads" CTA — header, mobile menu and every
     ad card — whose label must read white on that chip. */
  [class*="text-white"] { --tv-white: #ffffff !important; }

  /* ====================================================================
     Inputs — stable `tv-input` class (search box, email fields, filters)
     ==================================================================== */
  .tv-input, input.tv-input, textarea.tv-input {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .tv-input::placeholder { color: #8b949e !important; opacity: 1 !important; }
  /* tv-select: the search "All Time" / sort-scope filter pickers */
  .tv-select { background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  .tv-select * { color: #c4cdd6 !important; }
  input, textarea, select {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  input::placeholder, textarea::placeholder { color: #8b949e !important; opacity: 1 !important; }
  /* The site marks a focused field by swapping its border to the accent; our
     border-color above is `!important`, so it pinned the focused border to the
     same grey as the resting one. Give the accent back on focus. Deliberately
     kept to the plain `:focus`: matching the site's focused WRAPPER div needs a
     Level-4 pseudo-class the old userstyles.org parser has no precedent for, and
     the accent focus OUTLINE the site draws on that wrapper survives untouched,
     so the focused field stays clearly indicated either way. */
  .tv-input:focus, input.tv-input:focus, textarea.tv-input:focus,
  input:focus, textarea:focus { border-color: #5fb0e6 !important; }

  /* Segmented radio groups (the search box's Things / Makes / Users /
     Collections type picker). The site marks the chosen option with a selected
     FILL plus an accent border and accent label; the neutralizer ate the fill
     and the blanket `label` colour rule below flattened the label, leaving the
     border as the only surviving cue. Restore the full selected treatment. */
  [class*="RadioButtonGroup__radioButtonLabel"]:hover {
    background-color: #21262d !important; border-color: #4f86c6 !important; }
  [class*="RadioButtonGroup__radioButtonLabel"][class*="RadioButtonGroup__selected"] {
    background-color: #1d2a3a !important; color: #9bd4ff !important; border-color: #5fb0e6 !important; }
  [class*="RadioButtonGroup__selected"] [class*="PageHeaderSearch__typeName"] { color: #9bd4ff !important; }

  /* ====================================================================
     Headings + body text (atomic / hashed text classes bypass tokens)
     ==================================================================== */
  h1, h2, h3, h4, h5, h6 { color: #e6edf3 !important; }
  p, li, dd, dt, blockquote, figcaption, td, th, caption, label, time, small {
    color: #c4cdd6 !important; }
  /* Homepage hero tagline: the dark-navy "Thingiverse" brand word -> light */
  [class*="HomePageTagline"], [class*="HomePageTagline"] [class*="brand"] {
    color: #e6edf3 !important; }
  /* The "Supporter of the SOULCRAFTED initiative" chip in the tagline strip is a
     lone SVG whose pill is a hardcoded near-white path (#F6F7FA, stroked #EEEFF1)
     with every glyph path fill="black" — natively the pill melts into the white
     page and only the black wordmark reads. On dark it inverts into a glaring
     white blob. Flip the pill to the elevated surface and lift the glyphs, so it
     matches the SoulCrafted chip the footer already renders dark. */
  [class*="HomePageTagline__badgeIcon"] path[fill="#F6F7FA"] { fill: #1c2128 !important; }
  [class*="HomePageTagline__badgeIcon"] path[stroke="#EEEFF1"] { stroke: #2d333b !important; }
  [class*="HomePageTagline__badgeIcon"] path[fill="black"] { fill: #e6edf3 !important; }

  /* The footer newsletter wordmark is an inline SVG: "Thingiverse" is
     fill="currentColor" and follows the footer ink, but "Club" is a hardcoded
     #2B52FE drawn for the white page and reads 3.4:1 on the #0d1117 footer bar.
     Lift it to the same brand blue the rest of the theme uses on dark. The
     aria-label is the only stable hook — the SVG carries no class. */
  svg[aria-label="Thingiverse Club Logo"] path[fill="#2B52FE"] { fill: #5fb0e6 !important; }

  /* small muted card labels ("Featured", "Ad", metadata) -> readable grey */
  [class*="itemCardMeta"], [class*="ItemCardMeta"],
  [class*="adCardCaption"], [class*="AdCardCaption"] { color: #9aa4af !important; }

  /* ====================================================================
     Links — keep the Thingiverse / MakerBot blue identity, lifted
     ==================================================================== */
  a { color: #5fb0e6; }
  a:hover { color: #9bd4ff; }

  /* ====================================================================
     Tabs / segmented controls (Thing details / Files / Comments / Remixes /
     Makes / Apps). The site builds them from `tv-button--ghost`, whose accent
     label would make EVERY tab look selected — it overrides that with a muted
     `--tv-content-secondary`. Restore that, and give the selected tab the
     accent label + underline and the accent count chip.
     ==================================================================== */
  /* `[role="tab"]` only — a generic `[class*="Tab"] a` was over-matching the
     `TabContentDetail__detailsTabContent` panel (substring "Tab"), greying every
     content link inside it (tags, the license link, in-description links) that the
     site paints brand-blue. The real tabs are `Tabs__tab` buttons handled below. */
  [role="tab"] { color: #c4cdd6 !important; }
  [role="tab"]:hover { color: #e6edf3 !important; }
  [role="tab"][aria-selected="true"], [class*="active"][role="tab"] {
    color: #ffffff !important; border-bottom-color: #5fb0e6 !important; }

  [class*="Tabs__tab"].tv-button { color: #9aa4af !important; }
  [class*="Tabs__tab"].tv-button:hover { color: #e6edf3 !important; border-bottom-color: #e6edf3 !important; }
  [class*="Tabs__tab"].tv-button[class*="isActive"] {
    color: #9bd4ff !important; border-bottom-color: #5fb0e6 !important; }
  [class*="Tabs__tabCounter"] {
    background-color: #14181d !important; color: #9aa4af !important; border-color: #262c33 !important; }
  [class*="Tabs__isActive"] [class*="Tabs__tabCounter"] {
    background-color: #2563c9 !important; color: #ffffff !important; border-color: #2563c9 !important; }

  /* Active pagination page: the site underlines the inner <span>. */
  [class*="paginationItem"][class*="isActive"] > span { border-bottom-color: #e6edf3 !important; }

  /* ====================================================================
     Dropdown / menu / popover surfaces (sort + category + filter menus)
     ==================================================================== */
  [class*="Dropdown"], [class*="dropdown"], [class*="Menu"], [class*="menu"],
  [class*="Popover"], [class*="popover"], [class*="Tooltip"], [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  /* The header search panel and the mobile dropdowns each lay a full-viewport scrim
     (position:fixed, 100vw x 100vh) UNDER themselves, and its class name carries the
     `Menu`/`Dropdown` substring — so the surface rule above painted the scrim SOLID
     #1c2128 and typing in the search box blanked the entire page behind the suggestions.
     Put back a translucent dim (native is rgba(0,14,26,.25), deepened here so it still
     reads as a dim over an already-dark page). Must stay AFTER the rule above. */
  [class*="MenuOverlay"], [class*="menuOverlay"],
  [class*="DropdownOverlay"], [class*="dropdownOverlay"] {
    background-color: rgba(0, 14, 26, 0.55) !important; }

  [role="menuitem"], [role="option"], [class*="MenuItem"], [class*="menuItem"] {
    color: #e6edf3 !important; background-color: transparent !important; }
  [role="menuitem"]:hover, [role="option"]:hover,
  [class*="MenuItem"]:hover, [class*="menuItem"]:hover { background-color: #2d333b !important; }
  /* Recent-search rows in the header search panel carry their whole hover cue in a
     single-class `:hover` fill, which the neutralizer outranks — the row under the
     pointer is then identical to the rest of the list. */
  [class*="RecentSearches__recentSearchWrapper"]:hover { background-color: #18222f !important; }
  /* react-select marks the current choice with an accent fill; the blanket
     `[role="option"]` reset above would erase it, so it has to come after and
     out-specify it. */
  [role="option"][class*="react-select__option--is-selected"] {
    background-color: #2563c9 !important; color: #ffffff !important; }
  /* `--tv-border-disabled` resolves to `--tv-neutral-muted`, which the ramp above
     lifts to a light grey for MUTED TEXT — but the site also spends it as the
     react-select DISABLED control's border. Natively both controls are faint on
     white (disabled #afb4c0 ~2:1, enabled #eeeff1 ~1.1:1); on dark the light grey
     gave the dead control a 5.4:1 outline next to a 1.3:1 live one, so the
     unusable picker read as the actionable one. Keep the native relationship. */
  .react-select__control--is-disabled { border-color: #3f4854 !important; }

  /* Dropdown panels float over the elevated card surface and land on the same
     #1c2128, so the site's `0 2px 20px rgba(0,0,0,.15)` — the only thing that
     separates them on white — contributes nothing and the open menu reads as part
     of the card. A hairline ring restores the layer edge without the 2px reflow a
     real border would cause (the panel's own border-width is 0). */
  [class*="Dropdown__dropdownContent"] {
    box-shadow: 0 0 0 1px #3a424c, 0 4px 16px rgba(0, 0, 0, 0.6) !important; }

  /* Tooltips. `.tv-tooltip` (footer, share modal) is lowercase, so the
     `[class*="Tooltip"]` selector above never matched it: it kept painting
     `--tv-bg-inverse-secondary` under `--tv-content-inverse` white text.
     The `-arrow` elements are CSS triangles (three transparent borders + one
     coloured), so they must be given the tooltip's fill on the bottom edge
     ONLY — colouring all four sides renders them as a solid square. */
  .tv-tooltip, [class*="tv-tooltip--"], [class*="userTooltip--"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  .tv-tooltip-arrow, [class*="tv-tooltip-arrow"], [class*="userTooltipArrow"] {
    border-color: transparent transparent #1c2128 transparent !important; }

  /* react-toastify toasts (link copied, saved, errors). The `--toastify-color-light`
     retone above turns the default LIGHT toast into a dark panel, but the close button
     keeps react-toastify's own `color: #000` at opacity .3 — a black glyph on the dark
     panel, invisible. Lift it to the panel's ink so the .3 still reads as a muted grey. */
  .Toastify__close-button--light { color: #e6edf3 !important; }

  /* "Opening in Cura" modal (thing page > Files > Open in Cura). It renders in a
     ReactModal PORTAL outside #react-app, so the neutralizer never reaches it and
     its hardcoded near-black #000e1a paints as-is: the connector rule between the
     two illustrations, the arrow head after it, and the loading spinner between
     them all sit at ~1.3:1 on the dark modal, so the whole "site -> Cura" hand-off
     graphic reads as an empty gap. */
  [class*="OpenSlicerModal__openSlicerModalLine"] { background-color: #8b949e !important; }
  [class*="OpenSlicerModal__openSlicerModalArrow"] { color: #c4cdd6 !important; }
  /* Spinner variants are a hardcoded ink each. `black` (#000e1a) and `grayDark`
     (#525b75) were drawn for the white page; both are near-invisible on ours.
     `white`/`default`/`primary` already read on dark and are left alone. */
  [class*="Spinner__black"], [class*="Spinner__grayDark"] { color: #c4cdd6 !important; }

  /* Magic-link "check your inbox" step: the Resend button is a text button inked
     with the raw brand blue #2b52fe, drawn for the white auth card — 2:1 on the
     dark one. Same trap as its `iconCircle` sibling above. */
  [class*="CheckInboxView__resendButton"] { color: #9bd4ff !important; }

  /* ====================================================================
     NO blanket `* { border-color }` reset here. The site drives every border
     through the `--tv-border-*` tokens retoned above, so a blanket reset buys
     nothing and destroys a lot: it repainted the `border:1px solid transparent`
     that every `.tv-button` carries (boxing in every ghost button), erased the
     accent border that marks the selected sort pill, the selected gallery
     thumbnail, the selected filter chip and the active filter tab, greyed the
     "Work in Progress" badge's yellow ring and the checkbox outline, and filled
     all four sides of the tooltip's CSS-triangle caret so it rendered as a
     solid square. Anything genuinely too bright is handled by a token or by a
     scoped rule below.
     ==================================================================== */

  /* Mobile menu divider: the site's menu is brand blue, so it separates its
     sections with a near-white hairline (--tv-border-on-primary). Our menu is
     dark, so that hairline glares — mute it to the standard divider tone. */
  [class*="pageHeaderMobileMenu"] [class*="mobileSubSection"] { border-top-color: #2d333b !important; }

  /* Four widgets hardcode the SAME light scrollbar pair (#c9ccd4 track under a
     #525b75 thumb), each scoped tightly enough to beat our global scrollbar rule:
     the gallery thumbnail rail, the search Filters modal's scrolling body (open
     Filters > expand Categories), the comment textarea and the AddFeatures list.
     `scrollbar-color` matters as much as the `::-webkit-` pair — Chromium draws
     an overlay thumb with no track, but Firefox (the Stylus target) paints the
     full #c9ccd4 track as a bright strip down the panel edge. */
  [class*="carouselThumbnailsWrapper"] ::-webkit-scrollbar-track,
  [class*="SearchFilterModal__modalContentWrapper"] ::-webkit-scrollbar-track,
  [class*="autosizeTextareaWrapper"] ::-webkit-scrollbar-track,
  [class*="AddFeaturesModal__itemsListContainer"] ::-webkit-scrollbar-track {
    background: #14181d !important; }
  [class*="carouselThumbnailsWrapper"] ::-webkit-scrollbar-thumb,
  [class*="SearchFilterModal__modalContentWrapper"] ::-webkit-scrollbar-thumb,
  [class*="autosizeTextareaWrapper"] ::-webkit-scrollbar-thumb,
  [class*="AddFeaturesModal__itemsListContainer"] ::-webkit-scrollbar-thumb {
    background-color: #2d333b !important; }
  [class*="carouselThumbnailsWrapper"] *,
  [class*="SearchFilterModal__modalContentWrapper"] *,
  [class*="autosizeTextareaWrapper"] *,
  [class*="AddFeaturesModal__itemsListContainer"] * {
    scrollbar-color: #2d333b #14181d !important; }

  /* ====================================================================
     Image / thumbnail loading skeletons: light-grey -> dark, so empty
     slots don't glow white (true model previews/renders are untouched —
     they paint over their own <img>/<canvas>, which we never recolor).
     ==================================================================== */
  [class*="Skeleton"], [class*="skeleton"], [class*="Placeholder"], [class*="placeholder"],
  [class*="ImageWrapper"], [class*="imageWrapper"], [class*="Thumbnail"] {
    background-color: #1c2128 !important; }

  /* Media <img> own background: gallery photos default to a light element
     background that shows through transparent PNGs and during load. Set it to
     the dark surface — this paints BEHIND the image only (no filter, no tint),
     so true-color photos are untouched while transparent/loading areas go dark.
     (Note: previews the CDN bakes onto a white canvas via `?cbg=white` carry
     that white inside the JPEG pixels themselves — that's image content, not a
     themeable surface, so it's intentionally left as-is to avoid tinting.) */
  img.mediaItem--image, [class*="mediaItem"] img, [class*="Carousel"] img,
  [class*="carousel"] img { background-color: #1c2128 !important; }

  /* The site's "no image" fallback is a RASTER — `/site/img/default/Gears_*`, a #e8ebfb
     plate served at card size (292x264 on the legacy /apps grid), plus the
     grey-on-white default avatar. No background rule can reach pixels, and no DOM scan
     can see them either: audit-theme skips <img>, the element background is transparent
     and there is no text node. Neither asset carries dark ink — the Gears plate's
     DARKEST pixel is Y=156 of 255 — so inverting cannot bury linework; the hue-rotate
     keeps the result in the asset's own blue-lavender family rather than flipping it to
     brown. The `default/` path scope is load-bearing: real model previews and app logos
     must never be filtered. */
  img[src*="/site/img/default/"] { filter: invert(1) hue-rotate(180deg) !important; }

  /* /developers illustrates its three feature columns with greyscale rasters that
     bake an opaque #f5f5f5 plate into the file (three bright squares on the dark
     page), and its Thing Apps illustration is transparent line art whose brightest
     pixel is Y=102 (invisible on it). Both are greyscale, so inverting lifts the
     linework without shifting any hue; the fractional amount is what lands the
     #f5f5f5 plate on Y=24 — the page base is Y=23, so the plate stops reading as a
     square. The `developers-arrow` chevron is deliberately excluded: it is the
     brand blue and already reads. */
  img[src*="developers-explore"], img[src*="developers-community"],
  img[src*="developers-environment"], img[src*="developers-apps"] {
    filter: invert(0.94) !important; }

  /* /legal's card icons are greyscale rasters whose whole plate is dark (policy
     tops out at Y=51, terms at Y=153) — they were the figure against the white
     page and are now near-invisible on the card. Inverting keeps the plate/glyph
     relationship and puts the figure back. `privacy-policy` is already a light
     plate and is left alone; its path does not contain `/images/policy`. */
  img[src*="/site/assets/images/policy"], img[src*="/site/assets/images/terms"] {
    filter: invert(1) !important; }

  /* /about/advertising's "Our Previous Partners" strip shows third-party
     wordmarks as transparent PNGs drawn for the white page; three of the five
     currently listed are solid black (Y max 2) and vanish on the dark tile. The
     partner list rotates, so give the tile the light ground the logos are drawn
     for rather than filtering individual files — the same treatment the Google
     sign-in button gets above. `logoBadge` is the modifier that separates these
     tiles from the stat and CTA badges sharing the `aboutAdvertisingBadge` base. */
  [class*="AboutAdvertisingPage__logoBadge--"] {
    background-color: #e6edf3 !important; border-color: #e6edf3 !important; }

  /* ====================================================================
     Ad surrounds: dark frame + dark loading slot (don't theme iframe
     content). Google DFP slots have stable id prefixes.
     ==================================================================== */
  [class*="AdCard"], [class*="adCard"], [class*="Leaderboard"], [class*="leaderboard"],
  [id^="div-gpt-ad-"], [id*="google_ads_iframe"], ins.adsbygoogle {
    background-color: #14181d !important; }

  /* Publift's sticky footer ad wraps the creative in chrome of its own, present on
     every page: a full-width #efefef plate at opacity .3 (invisible on white, a
     bright band over the dark page) and an opaque #efefef collapse tab whose
     chevron is two #053067 bars. The plate and tab are the widget's surfaces, not
     the ad creative, so they follow the page; the chevron follows the tab. */
  [class*="publift-widget"][class*="container-background"] { background-color: #14181d !important; }
  [class*="publift-widget"][class*="-button"] { background-color: #1c2128 !important; }
  [class*="publift-widget"][class*="-button"] > div { background-color: #c4cdd6 !important; }

  /* ====================================================================
     Blog (/blog and /blog?p=<slug>) — the posts are a third-party Dropinblog
     embed with its own light palette under `#dib-posts` / `#dib-template-2` /
     `#dib-search-dialog`. It resolves no `--tv-*` token, and the `#react-app`
     neutralizer only reaches its `background-color`s, so its hairlines, its
     #333 ink and its dialog survive untouched. Its own rules are `#id`-scoped
     (several `!important`), so each override matches or beats that specificity.
     ==================================================================== */
  #dib-template-2 a.dib-post, .dib-related .dib-related-post,
  #dib-posts blockquote, #dib-search-box, #dib-search-dialog .dib-search-hits-item,
  #dib-posts .dib-faq-item { border-color: #2d333b !important; }
  #dib-posts .dib-related .dib-related-post h2 a.dib-post-title-link {
    color: #e6edf3 !important; }
  /* the in-post divider is a background stripe, not a border */
  #dib-posts .dib-post-content hr { background: #2d333b !important; }
  /* featured-image loading shimmer: a white->#eef1f4 sweep, animated by the
     widget's own `background-size`/`animation`, so only the image layer changes */
  img.dib-img-loading {
    background-image: linear-gradient(90deg, #1c2128 35%, #262c33 48%, #262c33 52%, #1c2128 65%) !important; }
  /* Blog search (the `dib-search-toggle` magnifier) opens a <dialog> outside
     #react-app with a hardcoded white panel and white result rows. */
  #dib-search-dialog { background-color: #1c2128 !important; }
  #dib-search-dialog .dib-search-hits-item a, #dib-search-dialog .ais-Hits--empty {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  #dib-search-dialog .dib-search-hits-item a:hover { background-color: #2d333b !important; }
  #dib-search-dialog .dib-search-hits-item mark {
    background-color: #3d3410 !important; color: #ffd75c !important; }
  #dib-posts #dib-search-close { color: #c4cdd6 !important; }

  /* ====================================================================
     Footer
     ==================================================================== */
  /* A lowercase `[class*="footer"]` is deliberately absent here: the legacy shell
     carries `fixed-footer` on <body>, so that substring matches the entire page —
     the descendant `a` form then outranks `.tv-button--primary` and repaints every
     header CTA label the footer link blue. The React footer is `Footer__footer*`;
     the legacy one is `.site-footer` / `.footer-links` inside `.page-container`. */
  footer, [class*="Footer"], .page-container .site-footer,
  .page-container .footer-links {
    background-color: #0d1117 !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  footer a, [class*="Footer"] a, .page-container .site-footer a,
  .page-container .footer-links a { color: #9bd4ff !important; }

  /* ====================================================================
     Legacy (non-React) pages — /challenges, /challenges/<slug>, /apps and
     the legacy 404. These are still served by the OLD Thingiverse stack:
     no `#react-app`, a `.page-container` shell, and the
     `build/{basic,main,challenges,apps}.css` stylesheets. Nothing above
     reaches them (every rule keys off `#react-app` or a hashed React class),
     so they shipped in the site's original LIGHT design — white
     `.content-box`/`.item`/`.app-card` panels — and our page-wide light ink
     lands on white, so the challenge copy and app titles wash out entirely.
     Retone the legacy palette (#fff surfaces, #ececec/#e7e7e7/#cbcbcb
     hairlines, #666/#333 ink, #ececec/#e4e4e4/#ddd fills) here.

     Every selector is scoped to `.page-container`, which exists ONLY on
     these pages, so the deliberately generic legacy class names (`.item`,
     `.icon`, `.modal`, `.more`) can never leak into the React UI. The
     shared header/footer/`tv-button` chrome is already handled above and
     renders correctly on these pages as-is.
     ==================================================================== */
  .page-container { background-color: #14181d !important; }
  .page-container .content-box, .page-container .item, .page-container .app-card,
  .page-container .challenge-header, .page-container .item-interactions,
  .page-container .interaction-title, .page-container .avatar-wrapper,
  .page-container .tab-nav, .page-container .tab-nav a, .page-container .dropdown-menu,
  .page-container .category-card, .page-container .group-mini, .page-container .user-info,
  .page-container .user-stats, .page-container .search-form, .page-container .comment-card,
  .page-container .modal-content, .page-container .gallery-main,
  .page-container .share-buttons, .page-container .screen {
    background-color: #1c2128 !important; }
  .page-container .content-box, .page-container .item, .page-container .item-interactions,
  .page-container .challenge-header, .page-container .challenge-desc,
  .page-container .interaction, .page-container .avatar-wrapper, .page-container .section-nav,
  .page-container .tab-nav, .page-container .tab-nav a, .page-container .dropdown-menu,
  .page-container .category-card, .page-container .group-mini, .page-container .thing-mini,
  .page-container .search-form, .page-container .pagination-view-more,
  .page-container .to-top, .page-container .button-icon, .page-container .table-list,
  .page-container .challenge-prizes > div, .page-container .content-separator,
  .page-container hr { border-color: #2d333b !important; }
  /* #ececec / #e4e4e4 / #ddd fills: row hovers, dividers and empty-slot tiles */
  .page-container .table-list-item:hover, .page-container .pagination-link:hover,
  .page-container .pagination-view-more:hover, .page-container .category-card:hover,
  .page-container .dropdown-option:hover, .page-container .card-footer,
  .page-container .inline-upload, .page-container .template-micro,
  .page-container .attachment-assets, .page-container .add_item,
  .page-container .add_item-instructions { background-color: #21262d !important; }
  /* the legacy #666 / #333 inks */
  .page-container .content-box, .page-container .content-box h1, .page-container .more,
  .page-container .copyright, .page-container .pagination-link,
  .page-container .pagination-view-more, .page-container .plain-nav,
  .page-container .plain-nav a, .page-container .plain-link, .page-container .read_more,
  .page-container .table-list, .page-container .table-list-header,
  .page-container .table-list-item, .page-container .icon, .page-container .modal,
  .page-container .text-card, .page-container .user-fullname, .page-container .user-about,
  .page-container .card-footer, .page-container .basic-page h1,
  .page-container .basic-page h3, .page-container .basic-page h4,
  .page-container section h1, .page-container .app-info, .page-container .select-menu,
  .page-container .item-name, .page-container .inline-upload p {
    color: #c4cdd6 !important; }
  /* The app-card title is an <a> carrying its own legacy #333, so `.item-name`
     above reaches it only by inheritance — which a direct declaration beats. */
  .page-container .item-name a { color: #c4cdd6 !important; }
  /* `.white-button` is a white slab (APP INFO / LAUNCH APP) floating on the app
     card's dark cover — keep it a raised, clearly-clickable control, just dark.
     It has no border natively, so give it one or it melts into that cover. */
  .page-container .white-button {
    background-color: #21262d !important; border: 1px solid #3a424c !important;
    color: #e6edf3 !important; }
  /* The legacy footer paints a light #f5f5f5 -> #e8e8e8 GRADIENT, so the dark
     background-COLOR the footer rule above sets never shows through it. Its
     wordmark is `thingiverse_logo.svg` loaded through an `<img>`, whose paths are
     `fill="currentColor"` — an <img> SVG is its own document, so that resolves to
     the SVG's default BLACK and no host-page rule can reach it. Once the bar is
     dark the wordmark disappears, so invert the raster instead. */
  .page-container .site-footer { background-image: none !important; }
  .page-container .site-footer .site-logo img { filter: invert(1) !important; }

  /* /customizer is a legacy page of its own (`#top.customizer-page`), built from
     `customizer.css` rather than the `.content-box`/`.item` vocabulary above. Two
     of its bands are white — the "Explore Customizers" section and the pair of
     `.cta` boxes at the foot — and the page-wide light ink lands on both, so every
     heading and paragraph there is white on white. */
  .page-container .customizer-explore { background-color: #14181d !important; }
  .page-container .customizer-page .cta {
    background-color: #1c2128 !important; border-color: #3a424c !important;
    color: #c4cdd6 !important; }
  /* Its other three bands are native brand colour (blue #10469c, green #72b878,
     grey #666) and each sets `color:#fff` on itself — which reaches the copy only
     by inheritance, so the blanket `p` ink above takes it (1.5:1 on the green).
     Pin the copy back to the white these bands are drawn for. */
  .page-container .customizer-page > header,
  .page-container .customizer-page > header p,
  .page-container .customizer-what-is, .page-container .customizer-what-is p,
  .page-container .customizer-contribute, .page-container .customizer-contribute p,
  .page-container .customizer-contribute h4 { color: #ffffff !important; }

  /* ====================================================================
     Scrollbars + selection
     ==================================================================== */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #14181d; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
  ::selection { background-color: #2563c9 !important; color: #ffffff !important; }
  hr { border-color: #2d333b !important; }
}
